using System;using System.Collections.Generic;using System.Linq;using System.Windows.Forms;
namespace AshkanFitPro {
 public partial class TrainerDialog:Form {
  readonly Trainer original;readonly List<Trainer> existing;readonly bool fa;
  public Trainer Value {get;private set;}
  public TrainerDialog(Trainer trainer,bool persian,List<Trainer> trainers){original=trainer;fa=persian;existing=trainers??new List<Trainer>();InitializeComponent();RightToLeft=fa?RightToLeft.Yes:RightToLeft.No;RightToLeftLayout=fa;Text=fa?"اطلاعات مربی | اشکان فیت":"Trainer details | AshkanFit";labelTitle.Text=fa?"پروفایل مربی":"TRAINER PROFILE";labelName.Text=fa?"نام مربی":"Trainer name";labelSpecialty.Text=fa?"تخصص":"Specialty";labelPhone.Text=fa?"شماره تماس":"Phone";buttonSave.Text=fa?"ذخیره تغییرات":"Save trainer";buttonCancel.Text=fa?"انصراف":"Cancel";if(trainer!=null){textName.Text=trainer.Name;textSpecialty.Text=trainer.Specialty;textPhone.Text=trainer.Phone;}buttonSave.Click+=SaveTrainer;buttonCancel.Click+=(s,e)=>{DialogResult=DialogResult.Cancel;Close();};}
  void SaveTrainer(object sender,EventArgs e){string name=textName.Text.Trim(),specialty=textSpecialty.Text.Trim(),phone=textPhone.Text.Trim();if(name.Length<2||specialty.Length<2){MessageBox.Show(fa?"نام و تخصص باید حداقل دو کاراکتر داشته باشند.":"Name and specialty must be at least two characters.");return;}if(phone.Length>0 && (phone.Length<7||phone.Any(c=>!char.IsDigit(c)&&c!='+'&&c!='-'&&c!=' '&&c!='('&&c!=')'))){MessageBox.Show(fa?"شماره تماس معتبر وارد کنید.":"Enter a valid phone number.");return;}if(existing.Any(t=>t.Id!=(original==null?Guid.Empty:original.Id)&&string.Equals(t.Name?.Trim(),name,StringComparison.OrdinalIgnoreCase)&&string.Equals(t.Phone?.Trim(),phone,StringComparison.OrdinalIgnoreCase))){MessageBox.Show(fa?"این مربی قبلاً ثبت شده است.":"This trainer already exists.");return;}Value=new Trainer{Id=original==null?Guid.NewGuid():original.Id,Name=name,Specialty=specialty,Phone=phone};DialogResult=DialogResult.OK;Close();}
 }
}
